import type { ToolEditorial } from "@/lib/seo-tools/content";

export const PERFORMANCE_BATCH_TOOL_EDITORIAL: Record<string, ToolEditorial> = {
  "page-weight-checker": {
    definition: "A Page Weight Checker estimates the total transfer size of a page by adding up its HTML, CSS, JavaScript, images, fonts and other resources, using resource hints and response sizes where they are available. Transfer size is the number of bytes that actually travel over the network, which is usually smaller than the decoded size because of compression. This is a size estimate rather than a timed speed test.",
    whyItMatters: "Every extra kilobyte has to travel over the visitor's connection, so heavy pages load slowly on mobile networks and constrained devices even when the server responds quickly. Large payloads are one of the most common reasons pages fail Largest Contentful Paint, and they directly increase bounce risk on product and landing pages. Tracking weight per template makes regressions visible before they reach search results.",
    howToUse: ["Paste the full page URL into the \"Page URL\" field, for example https://example.com/page.", "Press \"Analyze\" and wait for the resource inventory to be collected.", "Review the estimated total transfer size at the top of the results.", "Open the breakdown to see which resource types contribute the most bytes.", "Compare the same check across your main templates to find the heaviest outliers."],
    interpretation: ["The total is an estimate built from hints and response metadata, so treat it as a directional figure rather than an exact byte count.", "Images and JavaScript are usually the largest contributors; a page dominated by either deserves a closer look.", "Transfer size matters more than decoded size for load time because it reflects what the network actually carries.", "Two pages with similar totals can still feel different if one blocks rendering while the other streams progressively."],
    commonProblems: ["Hero and gallery images uploaded at full camera resolution with no resizing.", "JavaScript bundles that include entire frameworks for a few small interactions.", "Multiple analytics, chat and marketing tags each loading their own libraries.", "Webfont families loaded with many weights and styles that are never used."],
    fixes: ["Serve responsive, modern-format images sized to their display dimensions.", "Split JavaScript bundles and load non-critical code only when it is needed.", "Audit third-party tags and remove duplicates and retired tools.", "Subset webfonts and keep only the weights actually used in the design."],
    bestPractices: ["Set a weight budget per page template and check it after every release.", "Test with mobile network throttling, not only a fast office connection.", "Re-check weight after adding new plugins, embeds or design sections.", "Pair weight tracking with field data so size improvements can be tied to real user experience."],
    example: "A category page shows an estimated 4.2 MB total, with 3.1 MB coming from product thumbnails served as full-size PNGs. Converting those thumbnails to responsive AVIF variants brings the page under 1 MB and visibly shortens loading on a mid-tier phone.",
    limitations: "This tool estimates size from hints and response metadata; it cannot always measure resources that load conditionally or behind user interaction. It does not measure main-thread JavaScript cost, server response time or real-user timing, so pair it with field data for a complete picture.",
    faqs: [
      { question: "What is a good page weight to aim for?", answer: "There is no universal target, but keeping key templates under roughly 1-2 MB of transfer size is a sensible starting point for content pages, with tighter budgets for landing pages." },
      { question: "Does page weight directly affect rankings?", answer: "Weight itself is not a ranking factor, but it strongly influences loading experience metrics such as Largest Contentful Paint, which do feed into page experience signals." },
      { question: "Why does this estimate differ from another tool's number?", answer: "Tools differ in what they count: cached versus fresh loads, above-the-fold versus full page, transfer versus decoded size, and whether conditional resources are included." },
      { question: "Should I count third-party scripts in page weight?", answer: "Yes. They consume the visitor's bandwidth and processing budget regardless of who hosts them, so include them when setting budgets." },
      { question: "How often should page weight be rechecked?", answer: "Check it whenever templates change and on a regular schedule, because marketing tags and media tend to accumulate weight gradually over time." },
    ],
  },
  "image-weight-hint-checker": {
    definition: "An Image Weight Hint Checker scans a page for its image candidates and highlights the ones likely to be heavy, along with missing modern-format or dimension hints. It looks for signals such as legacy formats, absent responsive variants and images without explicit width and height. The output is a prioritized hint list, not a pixel-by-pixel audit.",
    whyItMatters: "Images are typically the largest share of page weight, often more than half of all transferred bytes. A single unoptimized hero or gallery image can outweigh the entire HTML, CSS and JavaScript combined. Because image fixes are usually mechanical, this check tends to produce some of the fastest performance wins available.",
    howToUse: ["Type or paste the page address into the \"Page URL\" box to start the image inventory.", "Press \"Analyze\" to collect the page's image candidates.", "Review the flagged images sorted by likely weight impact.", "Check which images lack modern formats such as AVIF or WebP.", "Note images missing explicit dimensions, since those also risk layout shift."],
    interpretation: ["Images flagged as large candidates deserve attention first because they dominate the potential savings.", "A missing modern-format hint means the image could probably be served in AVIF or WebP at a fraction of the size.", "Absent responsive variants suggest mobile visitors may be downloading desktop-sized files.", "Missing dimensions are both a weight signal and a layout-stability signal worth fixing together."],
    commonProblems: ["Photographs saved as PNG instead of a photographic format.", "Full-resolution uploads displayed as small thumbnails.", "No srcset or sizes attributes, so every device downloads the same large file.", "Decorative and below-the-fold images loading at full quality immediately."],
    fixes: ["Convert photographic images to AVIF or WebP with a sensible fallback.", "Generate responsive variants and serve them with srcset and sizes.", "Resize source uploads to the largest size actually displayed.", "Add explicit width and height attributes to every content image."],
    bestPractices: ["Automate image transformation at the CDN or CMS level instead of relying on manual exports.", "Keep original uploads reasonably sized; do not use the media library as an archive.", "Lazy-load below-the-fold images but never lazy-load the hero or LCP image.", "Re-audit image weight after theme changes, since new templates often reset image handling."],
    example: "A blog hero uploaded as a 3 MB PNG is flagged as the top candidate. Re-exporting it as AVIF at the displayed width shrinks it to about 180 KB with no visible difference, cutting the article's total weight nearly in half.",
    limitations: "The tool works from markup hints and cannot always fetch the true byte size of every variant, especially for images generated dynamically by scripts. Actual savings depend on image content, and final verification belongs in a timed test with real network conditions.",
    faqs: [
      { question: "Is AVIF always better than WebP?", answer: "AVIF usually compresses further than WebP for photographs, but encoding is slower and very old browsers lack support, so serve AVIF with a WebP or JPEG fallback." },
      { question: "Do I need both srcset and sizes?", answer: "Srcset provides the candidate files while sizes tells the browser how much layout space the image will occupy; without sizes the browser cannot pick the right candidate reliably." },
      { question: "Can image optimization hurt image SEO?", answer: "No, as long as filenames, alt text and surrounding context stay intact. Faster images can only help the pages that carry them." },
      { question: "Should background images be optimized too?", answer: "Yes, and consider whether a CSS background is even necessary; content images in markup get responsive loading features that CSS backgrounds do not." },
      { question: "Why do my images lack dimensions?", answer: "Many themes and page builders omit width and height. Adding them, or using aspect-ratio in CSS, reserves layout space and prevents shifts." },
    ],
  },
  "render-blocking-hint-checker": {
    definition: "A Render-Blocking Hint Checker flags scripts and stylesheets, typically those loaded in the document head, that are likely to delay first render. Browsers pause rendering to process synchronous scripts and to fetch stylesheets needed for the first paint. The tool identifies these patterns from markup so you can see what stands between the visitor and visible content.",
    whyItMatters: "Content cannot appear until render-blocking resources are processed, so a heavy head directly delays First Contentful Paint and often Largest Contentful Paint as well. Third-party widgets and oversized stylesheets frequently sneak into the head through plugins and tag managers. Clearing the critical path is one of the highest-leverage changes for perceived speed.",
    howToUse: ["Put the URL of the page whose head you want scanned into the \"Page URL\" field.", "Press \"Analyze\" to scan the document head for blocking patterns.", "Review the flagged scripts and stylesheets in order of likely impact.", "Check whether flagged scripts really need to run before first paint.", "Use the findings as a work list for deferring, inlining or removing resources."],
    interpretation: ["Stylesheets in the head block rendering by design; the question is whether each one is needed for above-the-fold content.", "Synchronous scripts without defer or async block the HTML parser wherever they appear.", "Stylesheets with media attributes for print or non-matching viewports are generally non-blocking.", "@import chains inside CSS files serialize downloads and are a classic hidden blocker."],
    commonProblems: ["Entire CSS frameworks loaded in the head when only a fraction styles above-the-fold content.", "Chat, review or personalization scripts placed synchronously before the content.", "Webfont stylesheets that block text rendering while fonts download.", "Plugin-injected scripts that site owners never chose to put in the head."],
    fixes: ["Add defer to scripts that do not need to run before parsing completes, or async where order does not matter.", "Inline critical CSS for above-the-fold content and load the remaining stylesheet asynchronously.", "Move non-essential third-party scripts to load after first paint or on user interaction.", "Replace CSS @import with direct link tags."],
    bestPractices: ["Keep the document head lean; every tag there should justify its place on the critical path.", "Audit the head after installing new plugins, themes or tag-manager containers.", "Prefer native async and defer attributes over custom script loaders for basic cases.", "Verify improvements with both lab tests and real-user field data."],
    example: "A product page loads a review widget script synchronously in the head, delaying first paint by over a second. Adding defer lets the content paint first while the widget initializes moments later, with no visible loss of functionality.",
    limitations: "This is static markup analysis; it cannot measure how many milliseconds each resource actually blocks in a real browser. Some flagged resources may already be mitigated by HTTP/2 prioritization or caching, so confirm impact with timed testing before major refactors.",
    faqs: [
      { question: "Is all CSS render-blocking?", answer: "Stylesheets needed for the current viewport block rendering until loaded. Stylesheets scoped with non-matching media attributes, or loaded asynchronously, do not block first paint." },
      { question: "When should I use defer versus async?", answer: "Use defer for scripts that need the full document parsed and must run in order. Use async for independent scripts like analytics where execution order does not matter." },
      { question: "Are CSS @import statements really that bad?", answer: "Yes for performance. Each @import is discovered only after its parent stylesheet downloads, creating a sequential chain that link tags avoid." },
      { question: "Does preloading fix render-blocking resources?", answer: "Preload makes a resource arrive earlier but does not change whether it blocks rendering. It helps for genuinely critical files, not as a blanket fix." },
      { question: "Can I just move all scripts to the footer?", answer: "Footer placement helps, but defer and async are more reliable and keep execution order predictable. Scripts the page needs immediately still belong in a non-blocking head pattern." },
    ],
  },
  "lazy-load-image-checker": {
    definition: "A Lazy Load Image Checker examines a page's images to see whether below-the-fold ones use loading=\"lazy\" or an equivalent deferred-loading pattern. Lazy loading tells the browser to postpone offscreen images until the visitor scrolls near them, saving initial bytes. The tool reports which images defer loading and which load eagerly.",
    whyItMatters: "Deferring offscreen images shrinks the initial payload and lets visible content arrive sooner, which helps both perceived speed and Largest Contentful Paint. On long articles and listing pages the savings can be dramatic. Done wrong, however, lazy loading delays the very image users see first, so the distinction between above and below the fold matters enormously.",
    howToUse: ["Add the page URL to the \"Page URL\" field so its images can be inventoried.", "Press \"Analyze\" to inventory the page's images and their loading attributes.", "Review which images are marked lazy and which load eagerly.", "Confirm the hero or likely LCP image is NOT lazy-loaded.", "Check that lazy images still carry width and height so they do not cause layout shift."],
    interpretation: ["Below-the-fold images with loading=\"lazy\" are following the recommended pattern.", "An eager hero or LCP image is correct; lazy-loading it would delay the most important visual.", "Images with no loading attribute default to eager, which is wasteful far below the fold.", "JavaScript-only lazy loading without the native attribute may leave images invisible to simpler crawlers and older browsers."],
    commonProblems: ["Lazy-loading the hero image, which directly worsens Largest Contentful Paint.", "Applying lazy loading to every image including ones in the initial viewport.", "Lazy images without dimensions, causing content to jump when they load.", "Carousel slides below the fold loading eagerly on page start."],
    fixes: ["Add loading=\"lazy\" to genuinely below-the-fold images.", "Give the LCP image loading=\"eager\" and fetchpriority=\"high\" instead.", "Always pair lazy loading with explicit width and height or aspect-ratio.", "Defer offscreen carousel slides and video posters the same way."],
    bestPractices: ["Treat the fold as a per-template decision and document which images must stay eager.", "Test Largest Contentful Paint after changing lazy-loading behavior.", "Combine lazy loading with responsive images so deferred files are also small.", "Revisit lazy-load rules after redesigns change what sits above the fold."],
    example: "A long guide with forty screenshots loads them all eagerly, adding 6 MB to the initial page. Marking the below-the-fold screenshots lazy cuts the initial transfer to under 1 MB while the reading experience stays identical.",
    limitations: "The tool cannot see the visitor's actual viewport or scroll behavior, so its above-versus-below-the-fold judgment is heuristic. Images injected by scripts after load may not be visible to static analysis.",
    faqs: [
      { question: "Does lazy loading hurt image SEO?", answer: "Native lazy loading is understood by search crawlers, so indexed images are generally unaffected. Avoid JavaScript-only techniques that hide image URLs from crawlers." },
      { question: "Should the LCP image ever be lazy-loaded?", answer: "No. The LCP image should load eagerly with high fetch priority so it paints as early as possible." },
      { question: "What does decoding=\"async\" do?", answer: "It lets the browser decode the image off the main thread, reducing jank during scrolling. It is a small but worthwhile addition to content images." },
      { question: "Can I lazy-load background images?", answer: "CSS backgrounds do not support the loading attribute. Use IntersectionObserver-based JavaScript or reconsider whether the image needs to be a background." },
      { question: "Should iframes be lazy-loaded too?", answer: "Yes, below-the-fold iframes such as maps and videos benefit from loading=\"lazy\" just like images do." },
    ],
  },
  "core-web-vitals-guide": {
    definition: "A Core Web Vitals Guide Checker summarizes the on-page factors that commonly influence Largest Contentful Paint, Interaction to Next Paint and Cumulative Layout Shift for a given URL. It translates a page's markup and resource patterns into per-metric guidance rather than reporting measured scores. Think of it as a diagnostic map of where each vital is likely won or lost.",
    whyItMatters: "Core Web Vitals feed into Google's page experience signals, and they are assessed at the 75th percentile of real user visits, so template-level issues affect a large share of traffic. Each metric has different causes: LCP is about loading, INP about responsiveness and CLS about visual stability. Knowing which factor belongs to which metric keeps optimization work focused instead of scattershot.",
    howToUse: ["Supply the page you want diagnosed in the \"Page URL\" field.", "Press \"Analyze\" to generate the per-metric factor summary.", "Read the LCP section first, since loading issues are usually the most visible.", "Move to the INP section and look for heavy JavaScript patterns.", "Finish with the CLS section and note any unreserved space for images, ads or embeds."],
    interpretation: ["Good thresholds are LCP at or under 2.5 seconds, INP at or under 200 milliseconds and CLS at or under 0.1, measured at the 75th percentile of real visits.", "A page can pass two vitals and fail the third; each metric needs its own fixes.", "On-page factors explain likely causes, but the official verdict always comes from field data.", "Lab measurements are useful for debugging but do not replace real-user numbers."],
    commonProblems: ["Slow server responses inflating every metric at once.", "Unoptimized hero images or late-discovered LCP elements.", "Long JavaScript tasks blocking the main thread and hurting INP.", "Images, ads and embeds without reserved space causing layout shift."],
    fixes: ["Preload the LCP image and serve it eagerly with high fetch priority.", "Break up long tasks, defer non-critical JavaScript and reduce main-thread work for INP.", "Reserve space with width, height or aspect-ratio for all media and embeds.", "Stabilize ad slots and dynamic content areas with fixed-size containers."],
    bestPractices: ["Fix templates rather than individual pages, since vitals issues almost always repeat site-wide.", "Monitor field data over time; lab scores fluctuate with test conditions.", "Prioritize the metric failing for the most URLs first.", "Re-measure after each release that touches media, scripts or layout."],
    example: "A news article fails CLS because in-article ads inject without reserved space. Giving each ad slot a fixed-size container removes the shifts, and the template fix improves CLS across thousands of articles at once.",
    limitations: "This tool analyzes on-page factors only; it cannot report your actual Core Web Vitals, which come from real-user field data. Server geography, device mix and network conditions all influence the official numbers beyond what markup analysis can see.",
    faqs: [
      { question: "Are Core Web Vitals direct ranking factors?", answer: "They contribute to page experience signals used in ranking, but they are one input among many. Great vitals will not rescue thin content, and great content can rank with imperfect vitals." },
      { question: "What is the difference between INP and FID?", answer: "INP replaced FID in 2024. FID measured only the first interaction's delay, while INP measures responsiveness across the whole visit, making it a fuller picture of interactivity." },
      { question: "What does the 75th percentile mean?", answer: "It means 75 percent of real page visits must meet the threshold. A fast median is not enough if the slowest quarter of visits still struggles." },
      { question: "Why do lab and field results disagree?", answer: "Lab tests use simulated devices and networks at one moment in time, while field data reflects your actual visitors' devices, networks and behavior over 28 days." },
      { question: "How quickly do fixes show up in field data?", answer: "Field data rolls over roughly 28 days, so improvements appear gradually as new visits replace old ones in the window." },
    ],
  },
  "font-loading-checker": {
    definition: "A Font Loading Checker inspects the font-related link tags and CSS on a page for patterns that delay text rendering. It looks at how webfonts are requested, whether font-display is set, how many families and weights load, and whether the browser gets early hints to the font origin. The result is a focused review of everything standing between the visitor and readable text.",
    whyItMatters: "Text is usually the first thing visitors try to read, yet webfonts can leave it invisible or cause it to snap into a new style mid-read. Each additional font weight is another download competing with content on the critical path. Because typography touches every page, small font-loading fixes compound across the whole site.",
    howToUse: ["Enter the page address in the \"Page URL\" field to inspect its font requests.", "Press \"Analyze\" to inventory font requests and related link tags.", "Review the font-display values reported for each webfont.", "Check how many families and weights the page actually loads.", "Look for missing preconnect hints to font origins such as the font CDN."],
    interpretation: ["A missing font-display declaration risks invisible text while fonts download, the classic flash of invisible text.", "font-display: swap shows fallback text immediately and swaps when the webfont arrives, which is usually the right tradeoff.", "Loading many weights of several families multiplies downloads; most designs need far fewer.", "A preconnect hint to the font origin, with the crossorigin attribute, shaves round trips off the font request."],
    commonProblems: ["No font-display set, leaving text invisible during font download.", "Entire font families loaded when only regular and bold are used.", "Font stylesheets placed as render-blocking requests in the head.", "Missing preconnect to the font CDN, adding DNS and TLS delays."],
    fixes: ["Set font-display: swap on @font-face rules so text renders immediately.", "Preload the one or two critical woff2 files used above the fold.", "Add a preconnect hint with crossorigin to the font origin.", "Subset fonts to the character sets and weights the site actually uses."],
    bestPractices: ["Limit the design to two or three font families with minimal weights.", "Self-host fonts when you want full control over caching and subsetting.", "Use a system font stack for body text if brand constraints allow it.", "Audit font usage after redesigns, which often accumulate new families silently."],
    example: "A landing page loads six weights of a display font plus four of a body font, delaying text by over a second on mobile. Keeping two weights, adding font-display: swap and preconnecting to the font origin makes headlines readable almost immediately.",
    limitations: "Static analysis can flag risky patterns but cannot measure the actual flash-of-invisible-text duration, which depends on network timing and caching. Variable fonts and unicode-range subsetting add nuance that hint-level checks simplify.",
    faqs: [
      { question: "What is the difference between FOIT and FOUT?", answer: "FOIT is a flash of invisible text while the browser waits for the webfont. FOUT is a flash of unstyled text where a fallback shows first and then swaps. font-display controls which behavior you get." },
      { question: "Should I always use font-display: swap?", answer: "Swap is the safest default for content text. For decorative display type where a swap would be jarring, optional or fallback can be better choices." },
      { question: "Should I preload every webfont?", answer: "No. Preload only the critical one or two files used above the fold; preloading everything wastes bandwidth and can delay more important resources." },
      { question: "Is self-hosting fonts better than a font CDN?", answer: "Self-hosting gives you control over subsetting, caching headers and versioning, and removes a third-party dependency. A good CDN is fine too if you preconnect and configure it well." },
      { question: "Do variable fonts help performance?", answer: "Often yes. One variable font file can replace many static weight files, though the single file may be larger, so test the tradeoff for your usage." },
    ],
  },
  "third-party-script-checker": {
    definition: "A Third-Party Script Checker lists the external script hosts a page loads and highlights their likely performance and privacy cost. It distinguishes first-party resources from scripts served by analytics providers, ad networks, chat vendors, social platforms and tag managers. The output is an inventory of who else is running code on your pages.",
    whyItMatters: "Third-party scripts consume the same bandwidth, CPU and battery as your own code, yet they arrive with code you did not write and cannot easily optimize. A single slow vendor can delay interactivity for every visitor, and tag managers make it easy for marketing tags to multiply unnoticed. Most sites are surprised by how long their third-party list has grown.",
    howToUse: ["Paste the URL you want inventoried for external scripts into the \"Page URL\" field.", "Press \"Analyze\" to enumerate the third-party script hosts found.", "Review each host and identify which business purpose it serves.", "Flag vendors you no longer use or never approved.", "Treat the list as the starting point for a tag audit, not the final verdict."],
    interpretation: ["A long host list usually means overlapping tools doing similar jobs, which is the first thing to consolidate.", "Hosts loading synchronously or early in the document deserve scrutiny because they compete with your content.", "Tag manager containers hide their real payload; the container script is only the visible tip.", "Unknown hosts warrant investigation, since they may come from compromised plugins or forgotten experiments."],
    commonProblems: ["Multiple analytics and heatmap tools collecting the same data.", "Chat widgets and review badges loading on every page including checkout.", "Retired A/B testing or personalization tools still firing.", "Social embeds pulling in large SDKs for a single button."],
    fixes: ["Remove vendors that are no longer in use and consolidate overlapping tools.", "Load non-critical third parties asynchronously or after user interaction.", "Use facade patterns for heavy embeds like video and chat so they load on click.", "Self-host critical scripts where licensing allows it."],
    bestPractices: ["Establish tag governance: every new tag needs an owner and a removal date.", "Set a budget for third-party JavaScript just as you would for your own code.", "Prefer vendors that offer lightweight or async-first snippets.", "Monitor third-party failures, since a down vendor should never break your page."],
    example: "A checkout page loads twelve marketing scripts, and one retired testing tool alone adds 400 ms of main-thread work. Removing the retired tool and deferring the rest to after conversion events speeds up the final step without losing any active measurement.",
    limitations: "The tool sees script hosts, not what tag-manager containers inject at runtime, so the true payload may be larger than listed. It cannot measure each vendor's exact main-thread cost without timed profiling in a real browser.",
    faqs: [
      { question: "Do third-party scripts affect SEO?", answer: "Indirectly but really. They slow loading and interactivity, which feeds into page experience signals, and heavy scripts can even interfere with rendering content for crawlers." },
      { question: "Is loading scripts asynchronously enough?", answer: "Async prevents parser blocking but the scripts still download, parse and execute on the main thread. Truly non-critical vendors should be deferred further or removed." },
      { question: "What is the facade pattern?", answer: "A facade shows a lightweight placeholder, like a video thumbnail, and loads the heavy third-party embed only when the visitor interacts with it." },
      { question: "Does the tag manager itself count as third-party?", answer: "Yes, and it is often the heaviest one because it is a delivery mechanism for many more tags. Audit the container's contents, not just the container script." },
      { question: "Are third-party scripts a privacy concern too?", answer: "They can be. Each vendor may set cookies or collect behavioral data, so every tag should also pass a privacy review, not only a performance one." },
    ],
  },
  "caching-header-checker": {
    definition: "A Caching Header Checker reviews the Cache-Control, ETag, Last-Modified and related response headers for a page's resources. These headers tell browsers and CDNs how long each file may be reused without asking the server again. The tool highlights static assets that could be cached far more aggressively than they currently are.",
    whyItMatters: "Repeat visits should be nearly instant, but that only happens when static assets are cached properly. Without long-lived caching, returning visitors re-download the same stylesheets, scripts and images on every visit. Correct headers are also what let CDNs serve your assets from the edge instead of your origin.",
    howToUse: ["Enter the page URL in the \"Page URL\" field to fetch its caching headers.", "Press \"Analyze\" to fetch the caching headers for the page and its key assets.", "Review the max-age values reported for stylesheets, scripts and images.", "Check whether versioned files use the immutable directive.", "Confirm the HTML document itself is not cached so aggressively that updates get stuck."],
    interpretation: ["Long max-age values on static assets mean repeat visits stay fast; short values mean visitors re-download too often.", "The immutable directive on fingerprinted files tells the browser the content will never change at that URL.", "HTML documents usually deserve short or no-cache lifetimes so content updates appear promptly.", "ETag and Last-Modified enable efficient revalidation when a full long cache is not appropriate."],
    commonProblems: ["Versioned assets cached for minutes instead of a year.", "Missing immutable on fingerprinted filenames.", "HTML cached for hours, delaying content and price updates.", "No validation headers, forcing full re-downloads instead of cheap revalidation."],
    fixes: ["Serve fingerprinted static files with Cache-Control: public, max-age=31536000, immutable.", "Keep HTML cache lifetimes short or use no-cache with ETag validation.", "Add ETag or Last-Modified where conditional requests make sense.", "Align CDN caching rules with origin headers instead of letting defaults win."],
    bestPractices: ["Fingerprint asset filenames with content hashes on every deploy.", "Separate caching strategy by content type: immutable for assets, fresh for HTML.", "Verify headers at the CDN edge, not only at the origin.", "Include API responses in the caching review where they are cacheable."],
    example: "A site's logo and stylesheets carry a one-hour max-age, so daily visitors re-download them constantly. Adding content-hash filenames with a one-year immutable cache makes repeat visits load the shell instantly.",
    limitations: "The tool reads the headers returned for the fetched URLs; personalized or geo-varied responses may carry different headers for other visitors. It cannot change server or CDN configuration, which is where the actual fix happens.",
    faqs: [
      { question: "What does immutable actually do?", answer: "It tells the browser the file at this URL will never change, so it can skip revalidation entirely for the max-age duration. It is only safe with fingerprinted filenames." },
      { question: "Should HTML pages be cached?", answer: "Lightly. Short lifetimes or must-revalidate keep content fresh while still allowing some reuse. Aggressive HTML caching is a common cause of stale pages." },
      { question: "How do I bust the cache when files change?", answer: "Change the filename with a content hash on each build. The new URL is fetched fresh while old URLs remain valid in existing caches." },
      { question: "Does caching affect SEO?", answer: "Not directly, but faster repeat visits improve engagement signals and crawl efficiency, since crawlers also benefit from well-cached assets." },
      { question: "What about service workers?", answer: "Service workers add a programmable cache layer on top of HTTP caching. They are powerful but add complexity, so get HTTP headers right first." },
    ],
  },
  "compression-hint-checker": {
    definition: "A Compression Hint Checker inspects the content-encoding response header to see whether the main document is served with gzip, Brotli or no compression at all. Text-based assets such as HTML, CSS and JavaScript shrink dramatically under compression, often to a fraction of their original size. The tool reports what encoding, if any, the server applied.",
    whyItMatters: "Uncompressed text is one of the most wasteful ways to spend bandwidth: a 400 KB HTML document can travel as roughly 60 KB with Brotli. Because compression applies to every text response, enabling it is a one-time server change that benefits every page. Its absence is pure overhead with no upside.",
    howToUse: ["Provide the page address in the \"Page URL\" field to read its encoding headers.", "Press \"Analyze\" to read the content-encoding header of the main document.", "Check whether the response uses Brotli, gzip or nothing.", "Note the document size, since larger text files gain the most.", "Extend the review to CSS, JavaScript and API responses, which compress just as well."],
    interpretation: ["Brotli (br) is the modern preferred encoding and typically 15 to 25 percent smaller than gzip for text.", "Gzip is universally supported and still a large improvement over no compression.", "No content-encoding on a text response means the server is sending avoidable bytes.", "Images, video and already-compressed formats gain nothing from text compression and should be excluded."],
    commonProblems: ["Compression never enabled on the origin server.", "CDN serving gzip while the origin could negotiate Brotli.", "Dynamic pages and API responses left uncompressed.", "Compression applied to already-compressed images and fonts, wasting CPU."],
    fixes: ["Enable Brotli at the CDN or origin for text content types.", "Ensure HTML, CSS, JavaScript, SVG and JSON responses are all covered.", "Let the CDN handle negotiation so the best encoding the client supports is used.", "Precompress static assets at build time for maximum ratios."],
    bestPractices: ["Configure compression once at the CDN or edge rather than per application.", "Cover API and feed responses, not only pages.", "Monitor compression in synthetic tests so regressions get caught.", "Pair compression with minification; they multiply each other's savings."],
    example: "A category page's 380 KB HTML document arrives uncompressed. Enabling Brotli at the CDN shrinks it to about 55 KB, cutting time-to-first-byte payload dramatically for mobile visitors with no code changes.",
    limitations: "This check focuses on the main document's headers; full coverage requires reviewing every text asset type. It cannot enable compression itself, which remains a server or CDN configuration task.",
    faqs: [
      { question: "Is Brotli supported everywhere?", answer: "All modern browsers support Brotli over HTTPS. Servers negotiate automatically, falling back to gzip for older clients, so enabling it is safe." },
      { question: "Should images be compressed with gzip?", answer: "No. JPEG, PNG, WebP and AVIF are already compressed; running them through gzip wastes CPU for no size reduction. Optimize images with proper formats instead." },
      { question: "Does compression use a lot of server CPU?", answer: "Dynamic Brotli at high levels can cost CPU, which is why CDNs and precompression at build time are popular. The bandwidth savings almost always justify it." },
      { question: "How do I verify compression is working?", answer: "Check the content-encoding response header and compare the transferred size against the decoded size in browser developer tools." },
      { question: "What about zstd?", answer: "Zstd as HTTP content encoding is emerging and promising, but Brotli remains the widely supported modern choice for now." },
    ],
  },
  "critical-css-hint-checker": {
    definition: "A Critical CSS Hint Checker looks at a page's stylesheets and highlights the footprint of CSS alongside opportunities to inline the critical portion. Critical CSS is the minimum styling needed to render above-the-fold content; inlining it lets the first paint happen without waiting for full stylesheets. The tool gives a high-level read on where that optimization could pay off.",
    whyItMatters: "Stylesheets block rendering until downloaded and parsed, so a large CSS bundle delays everything the visitor sees. Most pages use only a fraction of their CSS above the fold, meaning visitors wait on styling they cannot even see yet. Extracting and inlining the critical subset is a classic fix for slow first paint.",
    howToUse: ["Type the page URL into the \"Page URL\" field to inventory its stylesheets.", "Press \"Analyze\" to inventory the page's stylesheets and their sizes.", "Review the total CSS footprint and the estimated unused share.", "Look at which stylesheets are render-blocking in the head.", "Use the inline candidates as input for a proper critical-CSS extraction."],
    interpretation: ["A large total CSS size with high unused share signals strong inlining and purging potential.", "Stylesheets flagged as render-blocking are the ones delaying first paint.", "Inline candidates point at above-the-fold styling worth extracting, not at inlining everything.", "Per-template results matter more than any single page, since CSS issues repeat across the theme."],
    commonProblems: ["A single monolithic stylesheet serving the entire site's design.", "CSS frameworks included wholesale when only utilities are used.", "@import chains delaying stylesheet discovery.", "Page-builder output with duplicated and dead rules."],
    fixes: ["Extract above-the-fold CSS and inline it in the document head.", "Load the remaining stylesheet asynchronously, for example with the print-media swap technique.", "Purge unused CSS per template with a build-time tool.", "Split stylesheets by template instead of shipping one global bundle."],
    bestPractices: ["Automate critical CSS extraction in the build pipeline rather than hand-maintaining it.", "Keep inlined critical CSS small so the HTML document itself stays lean.", "Re-extract after design changes, since critical CSS drifts out of date.", "Measure first-paint improvements in both lab and field data."],
    example: "A homepage ships 320 KB of CSS but needs only about 25 KB for the visible header and hero. Inlining that critical subset and deferring the rest moves first paint noticeably earlier on a throttled connection.",
    limitations: "This is a high-level hint based on stylesheet inventory, not a pixel-accurate above-the-fold extraction. True critical CSS depends on viewport, device and content, so final extraction needs dedicated tooling and visual verification.",
    faqs: [
      { question: "What exactly is critical CSS?", answer: "The subset of styles required to render the content visible without scrolling. Inlining it removes a render-blocking request from the critical path." },
      { question: "Does inlining CSS hurt caching?", answer: "Inlined CSS travels with the HTML on every visit instead of being cached separately, so keep the inlined portion small and the cacheable remainder in external files." },
      { question: "Is unused CSS an SEO problem?", answer: "Not directly, but it slows rendering, which affects page experience signals. It is a performance issue with SEO consequences." },
      { question: "How do I find my critical CSS?", answer: "Use build tools or services that render the page and extract used above-the-fold rules, then verify visually across breakpoints before deploying." },
      { question: "What about CSS frameworks?", answer: "Frameworks are fine if you purge unused rules at build time. Shipping the full framework unpurged is one of the most common CSS weight problems." },
    ],
  },
  "preconnect-hint-checker": {
    definition: "A Preconnect Hint Checker detects preconnect and dns-prefetch resource hints on a page and compares them against the third-party origins the page actually uses. Preconnect sets up DNS, TCP and TLS to an origin before it is needed, while dns-prefetch resolves only the domain name. The tool shows which origins get early-connection treatment and which are left to connect on demand.",
    whyItMatters: "Every new origin costs round trips for DNS lookup, connection setup and TLS negotiation before a single byte of content moves. For critical origins such as font CDNs, these round trips sit directly on the path to first paint. Well-placed hints recover that time; missing hints leave it on the table on every visit.",
    howToUse: ["Enter the URL to audit for resource hints in the \"Page URL\" field.", "Press \"Analyze\" to list the page's resource hints and third-party origins.", "Compare the hinted origins against the origins actually requested early.", "Check that font origins use preconnect with the crossorigin attribute.", "Remove hints pointing at origins the page no longer uses."],
    interpretation: ["Origins requested early without any hint are candidates for preconnect.", "Dns-prefetch suits origins needed later or with lower confidence; preconnect suits certain, early, critical origins.", "Font origins need the crossorigin attribute on the preconnect hint to match the actual font request.", "Hints to unused origins waste browser resources and should be pruned."],
    commonProblems: ["No preconnect to the font CDN despite webfonts on the critical path.", "Dozens of preconnect hints added speculatively, diluting their benefit.", "Preconnect to font origins missing the crossorigin attribute, forcing a second connection.", "Dns-prefetch used where full preconnect was warranted for a critical origin."],
    fixes: ["Add preconnect hints for the two to four most critical third-party origins.", "Include crossorigin on preconnect hints for font origins.", "Use dns-prefetch for lower-priority origins instead of full preconnect.", "Delete hints for vendors no longer on the page."],
    bestPractices: ["Reserve preconnect for origins certain to be needed above the fold.", "Keep the total number of preconnects small; each one costs browser resources.", "Place resource hints early in the document head.", "Verify the performance gain rather than assuming every hint helps."],
    example: "A site loads Google Fonts without any early hint, adding three round trips before text styling resolves. Adding preconnect hints with crossorigin to both font origins removes that delay from the critical path.",
    limitations: "Resource hints are advisory; the browser may ignore them under resource pressure. The tool cannot measure the exact milliseconds saved, which depends on network conditions and connection reuse.",
    faqs: [
      { question: "What is the difference between preconnect, dns-prefetch and preload?", answer: "Dns-prefetch resolves the domain only. Preconnect completes DNS plus connection and TLS setup. Preload fetches a specific file early. Each step up costs more but saves more when the resource is certain." },
      { question: "How many preconnects are too many?", answer: "Browsers handle only a handful well. Stick to a few critical origins; spraying preconnects at ten domains wastes the mechanism and can delay more important work." },
      { question: "Why does the font preconnect need crossorigin?", answer: "Font requests use CORS mode, and a preconnect without the matching crossorigin attribute opens an anonymous connection the font fetch cannot reuse." },
      { question: "Can I use preload instead of preconnect?", answer: "They solve different problems. Preload fetches a known file; preconnect warms up an origin for requests you cannot name in advance. Use both where each fits." },
      { question: "Does hint order in the head matter?", answer: "Earlier is generally better for critical hints, since the browser discovers and acts on them in document order." },
    ],
  },
  "mobile-performance-checklist": {
    definition: "A Mobile Performance Checklist generates a mobile-first performance checklist tailored to the business or page type you describe. It organizes the work into prioritized groups covering loading, interactivity, stability, media and network behavior on phones. The output is a practical action list, not a measurement of any specific page.",
    whyItMatters: "Most search traffic arrives on mobile devices over variable networks, and Google indexes the mobile version of pages. Desktop-only testing hides the slow CPUs, small viewports and flaky connections real visitors experience. A mobile-first checklist keeps optimization honest about the conditions that actually determine rankings and conversions.",
    howToUse: ["Describe your business or page type in the \"Topic or details\" field, for example \"Describe business or page type\" suggests a restaurant site or a product category page.", "Press \"Generate\" to build the tailored checklist.", "Work through the loading section first, since it affects every other metric.", "Assign owners to the interactivity and stability items, which often need developer time.", "Re-run the generator after major template changes to refresh priorities."],
    interpretation: ["Checklist items are ordered by typical impact, so start at the top rather than cherry-picking easy wins.", "Items marked as template-level fixes will repeat across the site and deserve central fixes.", "Some items require measurement tools to verify; the checklist tells you what to check, not the result.", "Treat unchecked items as backlog, not as failures, and track progress over releases."],
    commonProblems: ["Testing only on desktop and fast office wifi.", "Serving desktop-sized images and assets to phones.", "Intrusive interstitials and popups covering mobile content.", "Tiny tap targets and unreadable text sizes."],
    fixes: ["Serve responsive images and media sized for phone viewports.", "Test on a representative mid-tier Android device with throttled 4G.", "Replace intrusive interstitials with inline banners.", "Size tap targets comfortably and keep text legible without zooming."],
    bestPractices: ["Make mobile field data the source of truth for performance decisions.", "Include performance checks in the definition of done for new features.", "Keep a device lab or cloud-device subscription for regular testing.", "Review the checklist quarterly, since frameworks and third parties drift."],
    example: "A restaurant chain generates a checklist for its location pages and discovers every page loads a full-screen desktop hero video on phones. Replacing it with a lightweight poster image on mobile cuts load time dramatically for on-the-go searchers.",
    limitations: "A generated checklist is guidance, not a diagnosis; it cannot measure your pages or know your exact stack. Priorities may need adjusting for unusual architectures, and every item should be verified with real testing before and after changes.",
    faqs: [
      { question: "Should I optimize for mobile and desktop separately?", answer: "Start mobile-first, since it is the harder constraint and the indexed version. Most mobile fixes also improve desktop, while the reverse is rarely true." },
      { question: "Which device should I test on?", answer: "A mid-tier Android phone on throttled 4G represents the global median far better than a flagship on wifi. Test the middle, not the best case." },
      { question: "Is AMP still recommended?", answer: "AMP is no longer required for any search feature and most sites do better with fast responsive pages they fully control." },
      { question: "Do I need a separate mobile site?", answer: "No. Responsive design with one URL is the recommended approach; separate mobile URLs add canonicalization and maintenance risk." },
      { question: "Does a PWA help performance?", answer: "Service workers can make repeat visits instant, but they add complexity. Nail the basics of responsive performance first, then consider a PWA." },
    ],
  },
  "lcp-element-hint-checker": {
    definition: "An LCP Element Hint Checker highlights the elements on a page most likely to become the Largest Contentful Paint candidate, such as hero images, large text blocks, background images and video posters. LCP measures when the largest visible content element finishes rendering, so knowing which element that will be focuses optimization precisely. The tool identifies candidates from markup and resource patterns.",
    whyItMatters: "LCP carries the largest weight in Lighthouse's performance score and has a clear good threshold of 2.5 seconds at the 75th percentile. Optimizing the wrong element wastes effort while the real LCP candidate stays slow. Identifying the candidate first turns LCP work from guesswork into a targeted fix list.",
    howToUse: ["Paste the page URL into the \"Page URL\" field to surface its LCP candidates.", "Press \"Analyze\" to surface the likely LCP candidates.", "Note whether the top candidate is an image, a text block or a background.", "Check how the candidate is currently loaded: eagerly, lazily or late via script.", "Apply the candidate-specific fixes and re-test to confirm the LCP element changed or sped up."],
    interpretation: ["Image candidates are usually optimized through format, sizing, fetch priority and preloading.", "Text-block candidates point at font loading, render-blocking CSS or slow server response.", "Background-image LCP candidates are harder to prioritize because CSS backgrounds cannot take fetchpriority.", "If the candidate loads via JavaScript, discovery delay is likely a major part of the problem."],
    commonProblems: ["Hero images lazy-loaded, delaying the most important visual on the page.", "LCP images served in legacy formats at oversized dimensions.", "Hero implemented as a CSS background, losing preload and priority controls.", "Carousel heroes where the visible slide is discovered late."],
    fixes: ["Serve the LCP image eagerly with fetchpriority=\"high\" and consider preloading it.", "Convert the hero to AVIF or WebP at its displayed size.", "Replace CSS-background heroes with real img elements where possible.", "Simplify hero markup so the candidate is discoverable in the initial HTML."],
    bestPractices: ["Design heroes as static, early-discoverable elements rather than scripted showcases.", "Keep the LCP element's resource chain as short as possible.", "Monitor LCP in field data per template, not just in lab tests.", "Re-check the LCP candidate after redesigns, which often change it silently."],
    example: "A homepage hero loads lazily as a 2 MB JPEG inside a JavaScript carousel. Switching to an eager AVIF img with high fetch priority, preloaded in the head, moves LCP from over 4 seconds to under 2 seconds on mobile.",
    limitations: "Candidate identification is heuristic; the actual LCP element depends on viewport size, device and real loading conditions. Only field data or a real browser measurement can confirm which element truly paints largest.",
    faqs: [
      { question: "What counts as the LCP element?", answer: "The largest image, video or text block visible in the viewport during load. Browsers report whichever paints largest, and it can differ between mobile and desktop." },
      { question: "Can a text block be the LCP?", answer: "Yes. Large headlines often become the LCP, in which case font loading, CSS delivery and server response matter more than image optimization." },
      { question: "Why are background images bad for LCP?", answer: "CSS backgrounds are discovered late and cannot use fetchpriority or preload effectively, making them harder to optimize than regular img elements." },
      { question: "What does fetchpriority=\"high\" do?", answer: "It tells the browser this resource is critical so it gets bandwidth before lower-priority downloads. Use it sparingly, ideally only on the LCP image." },
      { question: "Why does lab LCP differ from field LCP?", answer: "Lab tests use one simulated viewport and network, while field data aggregates real visitors across devices, viewports and conditions over 28 days." },
    ],
  },
  "cls-risk-checker": {
    definition: "A CLS Risk Checker flags page elements that commonly cause Cumulative Layout Shift, such as images without dimensions, embeds without reserved space and dynamically injected content. CLS measures visual stability: how much the layout moves unexpectedly while loading. The tool reports risk patterns from markup before they annoy visitors.",
    whyItMatters: "Unexpected shifts frustrate readers and cause accidental clicks, which is why CLS has a good threshold of 0.1 at the 75th percentile. Shifts often come from ads, embeds and media added without reserved space, problems that are cheap to prevent but irritating to experience. Because the fixes are structural, one template change can stabilize thousands of pages.",
    howToUse: ["Add the page you want checked for shift risks to the \"Page URL\" field.", "Press \"Analyze\" to flag elements with layout-shift risk.", "Review images and videos missing explicit dimensions first.", "Check ad slots, embeds and iframes for reserved space.", "Look for banners, notices or widgets injected above existing content."],
    interpretation: ["Missing dimensions on media are the most common and most fixable CLS risk.", "Ad and embed slots without fixed-size containers will shift content when they fill.", "Late-injected content above the fold almost always causes visible movement.", "Webfont swaps can shift text, though usually less dramatically than unreserved media."],
    commonProblems: ["Images and videos without width and height attributes.", "Ad slots that collapse and expand as creatives load.", "Cookie banners and promo bars pushing content down after load.", "Social embeds and maps injected without placeholder space."],
    fixes: ["Add width and height to all media, or use aspect-ratio in CSS.", "Give ad slots fixed-size containers with styled placeholder backgrounds.", "Reserve space for embeds and lazy-loaded widgets before they load.", "Avoid inserting content above existing content after initial render."],
    bestPractices: ["Design layouts with reserved space as a default, not an afterthought.", "Use skeleton placeholders for dynamic regions.", "Test CLS with real user sessions, since lab runs may miss interaction-driven shifts.", "Review third-party embeds, which are the most frequent surprise source of shifts."],
    example: "An article page injects a newsletter banner between paragraphs two seconds after load, pushing readers' place down the screen. Reserving the banner's space in the initial layout eliminates the shift while keeping the signup visible.",
    limitations: "Static analysis finds structural risks but cannot measure actual shift scores, which depend on loading timing and user interaction. Some shifts only appear in real sessions, so field data remains the final judge.",
    faqs: [
      { question: "What actually causes layout shift?", answer: "Any visible element changing position after initial render: media loading without reserved space, injected content, late-loading ads or fonts swapping with different metrics." },
      { question: "Do width and height attributes really fix image shift?", answer: "Yes. They let the browser calculate the aspect ratio and reserve space before the file arrives, which is the standard fix for image-driven CLS." },
      { question: "How do ads affect CLS?", answer: "Ad slots that resize when creatives load are a top CLS offender. Fixed-size containers per ad size keep the layout stable regardless of what fills them." },
      { question: "What is a good CLS score?", answer: "At or under 0.1 at the 75th percentile of real visits is good. Between 0.1 and 0.25 needs improvement, and above 0.25 is poor." },
      { question: "Can user interactions cause CLS?", answer: "Shifts within 500 milliseconds of a user interaction are generally excluded from CLS, since expected movement after a click is not penalized." },
    ],
  },
  "performance-budget-generator": {
    definition: "A Performance Budget Generator creates a simple performance budget for HTML, CSS, JavaScript and image weight based on the business or page type you describe. A performance budget sets explicit size caps that new work must respect, turning speed from a vague aspiration into a measurable constraint. The output is a starting budget to refine, not a universal standard.",
    whyItMatters: "Without budgets, pages accumulate weight with every release until performance silently collapses. Budgets give teams a shared, objective limit to design against and a tripwire that catches regressions in CI before they ship. They translate performance goals into numbers everyone from designers to marketers can understand.",
    howToUse: ["Describe your business or page type in the \"Topic or details\" field, for example a checkout flow or a media-heavy blog.", "Press \"Generate\" to create the draft budget.", "Review the per-resource caps for HTML, CSS, JavaScript and images.", "Adjust the numbers to your audience's devices and networks.", "Enforce the budget in your build pipeline so violations block or warn on release."],
    interpretation: ["Per-resource caps show where the bytes are allowed to go; the total is the headline number to protect.", "Tighter budgets suit landing and checkout pages, while media-rich templates may justify more image headroom.", "Budgets are guardrails, not guarantees: a page under budget can still have slow interactions.", "Third-party scripts deserve their own cap so vendor sprawl cannot consume the whole budget."],
    commonProblems: ["No budget at all, so every release adds weight unchecked.", "Budgets set once and never enforced in CI.", "A single site-wide budget that ignores template differences.", "Ignoring third-party scripts, which then blow past the intended total."],
    fixes: ["Adopt per-template budgets reflecting each page type's real needs.", "Enforce budgets with Lighthouse CI or bundle-size checks on pull requests.", "Give third-party JavaScript its own separate cap.", "Review and tighten budgets quarterly as the team builds optimization skill."],
    bestPractices: ["Start budgets from current measurements, then ratchet them down gradually.", "Make one person or team the owner of each budget.", "Connect budgets to business metrics so stakeholders see the revenue case.", "Revisit budgets after redesigns and platform migrations."],
    example: "A blog sets a draft budget of 60 KB HTML, 80 KB CSS, 170 KB JavaScript and 600 KB images per article. When a new social plugin pushes JavaScript over the cap in CI, the team catches it before release and loads the plugin on interaction instead.",
    limitations: "Generated budgets are informed starting points, not scientifically derived limits for your specific audience. Real budgets should be calibrated against your field data, device mix and business goals, then enforced consistently to matter.",
    faqs: [
      { question: "What numbers should a performance budget use?", answer: "Start from your current medians per template, set caps slightly below them, and tighten over time. Common starting points are a few hundred kilobytes of JavaScript and around a megabyte of images for content pages." },
      { question: "How do I enforce a budget?", answer: "With automated checks: Lighthouse CI assertions, bundle-size limits on pull requests, or synthetic monitoring alerts that fire when pages exceed their caps." },
      { question: "Should budgets differ by page type?", answer: "Yes. A checkout page deserves a much stricter budget than a photo gallery. One global number is either too lax for critical pages or impossibly strict for rich ones." },
      { question: "Who should own the performance budget?", answer: "Ideally a performance-minded engineer or team with authority to block releases, backed by stakeholders who understand the business value of speed." },
      { question: "How often should budgets change?", answer: "Review them quarterly and after major releases. Budgets should get stricter as optimization improves, not looser as exceptions accumulate." },
    ],
  },
};
